export enum Category {
  PERFUME = 'PERFUME',
  BODY_SPRAY = 'BODY_SPRAY',
  BODY_OIL = 'BODY_OIL'
}

export enum Gender {
  MALE = 'MALE',
  FEMALE = 'FEMALE'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  category: Category;
  gender: Gender;
  description: string;
  notes: string;
  imageUrl: string;
  videoUrl?: string; // Optional mockup video URL
}

export interface CartItem extends Product {
  quantity: number;
}

export interface OrderDetails {
  customerName: string;
  phone: string;
  hostel: string;
  items: CartItem[];
  totalAmount: number;
  deliveryFee: number;
  paymentProof?: File;
}

import { GoogleGenAI, Type } from "@google/genai";
import { PRODUCTS } from "./constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function getScentRecommendation(answers: { mood: string, occasion: string, preference: string }) {
  const prompt = `Based on these user preferences for a fragrance:
  - Mood: ${answers.mood}
  - Occasion: ${answers.occasion}
  - Scent Preference: ${answers.preference}

  Recommend one product from this list: ${JSON.stringify(PRODUCTS.map(p => ({id: p.id, name: p.name, desc: p.description})))}.
  Provide a brief reason (1 sentence) why this is the perfect match.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            productId: { type: Type.STRING },
            reason: { type: Type.STRING }
          },
          required: ["productId", "reason"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return null;
  }
}

