          <a 
            href="#/order"
            onClick={onClose}
            className={`block w-full text-center bg-[#FFD700] text-black font-bold py-4 rounded-lg hover:bg-white transition-colors tracking-widest ${items.length === 0 ? 'opacity-50 pointer-events-none' : ''}`}
          >
            PROCEED TO ORDER
