import React, { useState, useMemo } from 'react';
import { useParams } from 'react-router-dom';
import { PRODUCTS } from '../constants';
import { Category, Gender, Product } from '../types';
import ProductCard from '../components/ProductCard';
import { Filter, User, UserCheck } from 'lucide-react';

interface CategoryPageProps {
  onAddToCart: (p: Product) => void;
}

const CategoryPage: React.FC<CategoryPageProps> = ({ onAddToCart }) => {
  const { categoryId } = useParams<{ categoryId: string }>();
  const [activeGender, setActiveGender] = useState<Gender | 'ALL'>('ALL');

  const category = categoryId as Category;

  const filteredProducts = useMemo(() => {
    return PRODUCTS.filter(p => 
      p.category === category && (activeGender === 'ALL' || p.gender === activeGender)
    );
  }, [category, activeGender]);

  const categoryTitle = category.replace('_', ' ');

  return (
    <div className="pt-24 pb-20 px-4">
      <div className="max-w-7xl mx-auto">
        <header className="mb-12">
          <h1 className="font-serif text-5xl text-[#FFD700] mb-4 uppercase tracking-tighter">
            {categoryTitle}S
          </h1>
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <p className="text-zinc-400 italic">
              Explore our selection of {categoryTitle.toLowerCase()}s for every style.
            </p>

            <div className="flex items-center bg-zinc-900 rounded-full p-1 border border-zinc-800">
              <button
                onClick={() => setActiveGender('ALL')}
                className={`px-6 py-2 rounded-full text-xs font-bold transition-all ${activeGender === 'ALL' ? 'bg-[#FFD700] text-black' : 'text-zinc-400 hover:text-white'}`}
              >
                ALL
              </button>
              <button
                onClick={() => setActiveGender(Gender.MALE)}
                className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeGender === Gender.MALE ? 'bg-[#FFD700] text-black' : 'text-zinc-400 hover:text-white'}`}
              >
                <User size={14} /> FOR HIM
              </button>
              <button
                onClick={() => setActiveGender(Gender.FEMALE)}
                className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeGender === Gender.FEMALE ? 'bg-[#FFD700] text-black' : 'text-zinc-400 hover:text-white'}`}
              >
                <UserCheck size={14} /> FOR HER
              </button>
            </div>
          </div>
        </header>

        {filteredProducts.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 animate-fade-in">
            {filteredProducts.map(product => (
              <ProductCard key={product.id} product={product} onAddToCart={onAddToCart} />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 border-2 border-dashed border-zinc-800 rounded-2xl">
            <p className="text-zinc-500 text-lg">No products found in this category for the selected filter.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CategoryPage;

import React, { useState } from 'react';
import { UNILAG_HOSTELS, DELIVERY_FEE, ACCOUNT_DETAILS } from '../constants';
import { CartItem } from '../types';
import { CheckCircle2, Upload, CreditCard, MapPin, Send } from 'lucide-react';

interface OrderPageProps {
  cartItems: CartItem[];
}

const OrderPage: React.FC<OrderPageProps> = ({ cartItems }) => {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    hostel: UNILAG_HOSTELS[0],
    notes: ''
  });
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [screenshot, setScreenshot] = useState<File | null>(null);

  const subtotal = cartItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const total = subtotal + DELIVERY_FEE;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!screenshot) {
      alert("Please upload payment screenshot before placing order.");
      return;
    }
    // In a real app, this would send data to a backend or WhatsApp API
    setIsSubmitted(true);
    window.scrollTo(0, 0);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setScreenshot(e.target.files[0]);
    }
  };

  if (isSubmitted) {
    return (
      <div className="pt-32 pb-20 px-4 text-center max-w-2xl mx-auto">
        <CheckCircle2 size={80} className="text-[#FFD700] mx-auto mb-6" />
        <h1 className="font-serif text-4xl text-white mb-4">Order Received!</h1>
        <p className="text-zinc-400 mb-8">
          Thank you for choosing Classic Wave, <strong>{formData.name}</strong>. We are verifying your payment. Your order will be delivered to <strong>{formData.hostel}</strong> within 24 hours.
        </p>
        <div className="bg-zinc-900 p-6 rounded-xl border border-zinc-800 text-left mb-8">
          <h3 className="text-[#FFD700] font-bold mb-4">ORDER SUMMARY</h3>
          <ul className="space-y-2 mb-4">
            {cartItems.map(item => (
              <li key={item.id} className="flex justify-between text-sm">
                <span className="text-white">{item.quantity}x {item.name}</span>
                <span className="text-zinc-500">₦{(item.price * item.quantity).toLocaleString()}</span>
              </li>
            ))}
          </ul>
          <div className="border-t border-zinc-800 pt-4 flex justify-between font-bold text-white">
            <span>TOTAL PAID</span>
            <span>₦{total.toLocaleString()}</span>
          </div>
        </div>
        <a href="#/" className="inline-block bg-[#FFD700] text-black font-bold px-8 py-3 rounded-full hover:bg-white transition-colors">
          RETURN TO SHOP
        </a>
      </div>
    );
  }

  if (cartItems.length === 0) {
    return (
      <div className="pt-32 pb-20 px-4 text-center">
        <h1 className="font-serif text-4xl text-white mb-6">Your cart is empty</h1>
        <p className="text-zinc-400 mb-8">Browse our collections to find your perfect scent.</p>
        <a href="#/category/PERFUME" className="bg-[#FFD700] text-black font-bold px-8 py-3 rounded-full hover:bg-white transition-colors">
          SHOP COLLECTIONS
        </a>
      </div>
    );
  }

  return (
    <div className="pt-32 pb-20 px-4">
      <div className="max-w-6xl mx-auto">
        <h1 className="font-serif text-5xl text-white mb-12 text-center">Checkout</h1>

        <div className="grid lg:grid-cols-2 gap-12">
          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-8 bg-zinc-950 p-8 rounded-2xl border border-zinc-900 shadow-xl">
            <h2 className="text-[#FFD700] font-serif text-2xl flex items-center gap-2">
              <MapPin size={24} /> Delivery Information
            </h2>

            <div className="grid gap-6">
              <div>
                <label className="block text-zinc-500 text-xs font-bold uppercase mb-2">Full Name</label>
                <input 
                  required
                  type="text" 
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-lg p-3 text-white focus:border-[#FFD700] focus:ring-1 focus:ring-[#FFD700] outline-none transition-all"
                  placeholder="e.g. John Doe"
                />
              </div>

              <div>
                <label className="block text-zinc-500 text-xs font-bold uppercase mb-2">WhatsApp Number</label>
                <input 
                  required
                  type="tel" 
                  value={formData.phone}
                  onChange={e => setFormData({...formData, phone: e.target.value})}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-lg p-3 text-white focus:border-[#FFD700] focus:ring-1 focus:ring-[#FFD700] outline-none transition-all"
                  placeholder="e.g. 08012345678"
                />
              </div>

              <div>
                <label className="block text-zinc-500 text-xs font-bold uppercase mb-2">UNILAG Hostel</label>
                <select 
                  value={formData.hostel}
                  onChange={e => setFormData({...formData, hostel: e.target.value})}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-lg p-3 text-white focus:border-[#FFD700] outline-none transition-all appearance-none"
                >
                  {UNILAG_HOSTELS.map(h => <option key={h} value={h}>{h}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-zinc-500 text-xs font-bold uppercase mb-2">Order Notes (Optional)</label>
                <textarea 
                  rows={2}
                  value={formData.notes}
                  onChange={e => setFormData({...formData, notes: e.target.value})}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-lg p-3 text-white focus:border-[#FFD700] outline-none transition-all"
                  placeholder="Anything we should know?"
                />
              </div>
            </div>

            <h2 className="text-[#FFD700] font-serif text-2xl flex items-center gap-2 pt-4">
              <CreditCard size={24} /> Payment Verification
            </h2>

            <div className="bg-zinc-900 p-6 rounded-xl border border-[#FFD700]/20">
              <p className="text-zinc-400 text-sm mb-4">
                Please make a transfer of <strong>₦{total.toLocaleString()}</strong> to the account below and upload the screenshot.
              </p>
              <div className="space-y-1">
                <div className="flex justify-between">
                  <span className="text-zinc-500 text-xs">Bank:</span>
                  <span className="text-white font-bold">{ACCOUNT_DETAILS.bank}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-zinc-500 text-xs">Account Name:</span>
                  <span className="text-white font-bold">{ACCOUNT_DETAILS.accountName}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-zinc-500 text-xs">Account Number:</span>
                  <span className="text-[#FFD700] font-mono font-bold tracking-widest">{ACCOUNT_DETAILS.accountNumber}</span>
                </div>
              </div>
            </div>

            <div className="relative border-2 border-dashed border-zinc-800 rounded-xl p-8 text-center hover:border-[#FFD700]/50 transition-colors group">
              <input 
                type="file" 
                accept="image/*" 
                className="absolute inset-0 opacity-0 cursor-pointer" 
                onChange={handleFileChange}
              />
              <Upload className="mx-auto text-zinc-600 mb-2 group-hover:text-[#FFD700] transition-colors" size={32} />
              <p className="text-zinc-400 text-sm">
                {screenshot ? <span className="text-[#FFD700] font-bold">{screenshot.name}</span> : 'Click or Drag to upload payment receipt'}
              </p>
            </div>

            <button 
              type="submit"
              className="w-full bg-[#FFD700] text-black font-bold py-4 rounded-full flex items-center justify-center gap-2 hover:bg-white transition-all transform hover:scale-[1.02]"
            >
              PLACE ORDER <Send size={18} />
            </button>
          </form>

          {/* Summary Sidebar */}
          <div className="space-y-6">
            <div className="bg-zinc-900/50 p-8 rounded-2xl border border-zinc-900 backdrop-blur-sm sticky top-28">
              <h2 className="text-white font-serif text-2xl mb-6">Order Summary</h2>
              <div className="space-y-4 mb-8 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
                {cartItems.map(item => (
                  <div key={item.id} className="flex gap-4 items-center">
                    <img src={item.imageUrl} className="w-12 h-16 object-cover rounded" alt={item.name} />
                    <div className="flex-1">
                      <p className="text-white text-sm font-medium">{item.name}</p>
                      <p className="text-zinc-500 text-xs">{item.quantity} x ₦{item.price.toLocaleString()}</p>
                    </div>
                    <span className="text-white font-bold text-sm">₦{(item.price * item.quantity).toLocaleString()}</span>
                  </div>
                ))}
              </div>

              <div className="space-y-3 border-t border-zinc-800 pt-6">
