import React, { useState } from 'react';
import { getScentRecommendation } from '../geminiService';
import { PRODUCTS } from '../constants';
import { Product } from '../types';
import { Sparkles, Loader2, RefreshCw, ShoppingCart } from 'lucide-react';

interface ScentQuizProps {
  onAddToCart: (p: Product) => void;
}

const ScentQuiz: React.FC<ScentQuizProps> = ({ onAddToCart }) => {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState({ mood: '', occasion: '', preference: '' });
  const [loading, setLoading] = useState(false);
  const [recommendation, setRecommendation] = useState<{ product: Product, reason: string } | null>(null);

  const questions = [
    {
      key: 'mood',
      title: 'How do you want to feel?',
      options: ['Powerful & Confident', 'Fresh & Energetic', 'Romantic & Sweet', 'Relaxed & Serene']
    },
    {
      key: 'occasion',
      title: "Where are you heading?",
      options: ['Class / Daily Grind', 'Night Out / Dinner', 'Special Date', 'Gym / Sports']
    },
    {
      key: 'preference',
      title: 'What notes do you prefer?',
      options: ['Woody & Spicy', 'Floral & Fruity', 'Fresh & Aquatic', 'Sweet & Oriental']
    }
  ];

  const handleSelect = (val: string) => {
    const key = questions[step].key;
    setAnswers({ ...answers, [key]: val });
    if (step < questions.length - 1) {
      setStep(step + 1);
    } else {
      processQuiz({ ...answers, [key]: val });
    }
  };

  const processQuiz = async (finalAnswers: typeof answers) => {
    setLoading(true);
    const result = await getScentRecommendation(finalAnswers);
    if (result) {
      const product = PRODUCTS.find(p => p.id === result.productId) || PRODUCTS[0];
      setRecommendation({ product, reason: result.reason });
    }
    setLoading(false);
  };

  const reset = () => {
    setStep(0);
    setAnswers({ mood: '', occasion: '', preference: '' });
    setRecommendation(null);
  };

  return (
    <div className="pt-32 pb-20 px-4 min-h-screen">
      <div className="max-w-3xl mx-auto">
        {!recommendation && !loading && (
          <div className="text-center">
            <h1 className="font-serif text-5xl text-white mb-6">Scent Persona Quiz</h1>
            <p className="text-zinc-400 mb-12">Let our AI curator find the fragrance that speaks to your soul.</p>

            <div className="bg-zinc-950 border border-zinc-900 p-8 rounded-2xl shadow-2xl animate-fade-in">
              <div className="mb-8">
                <span className="text-[#FFD700] font-bold text-xs tracking-widest uppercase">Question {step + 1} of 3</span>
                <h2 className="text-white text-2xl font-serif mt-2 italic">{questions[step].title}</h2>
              </div>

              <div className="grid gap-4">
                {questions[step].options.map((option) => (
                  <button
                    key={option}
                    onClick={() => handleSelect(option)}
                    className="w-full text-left p-4 rounded-xl border border-zinc-800 bg-zinc-900 text-zinc-300 hover:border-[#FFD700] hover:text-white transition-all transform hover:translate-x-2"
                  >
                    {option}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {loading && (
          <div className="text-center py-20 flex flex-col items-center animate-pulse">
            <Loader2 size={60} className="text-[#FFD700] animate-spin mb-6" />
            <h2 className="font-serif text-3xl text-white italic">Curating your signature essence...</h2>
            <p className="text-zinc-500 mt-4">Analyzing your aura for the perfect match</p>
          </div>
        )}

        {recommendation && (
          <div className="bg-zinc-950 border border-[#FFD700]/30 p-8 md:p-12 rounded-3xl shadow-2xl animate-fade-in">
            <div className="flex flex-col md:flex-row gap-8 items-center">
              <div className="w-full md:w-1/2">
                <img 
                  src={recommendation.product.imageUrl} 
                  className="w-full h-96 object-cover rounded-2xl shadow-xl border border-zinc-800" 
                  alt={recommendation.product.name} 
                />
              </div>
              <div className="w-full md:w-1/2">
                <div className="flex items-center gap-2 text-[#FFD700] mb-4">
                  <Sparkles size={20} />
                  <span className="text-xs font-bold tracking-[0.2em]">YOUR AI MATCH</span>
                </div>
                <h2 className="font-serif text-4xl text-white mb-2">{recommendation.product.name}</h2>
                <p className="text-[#FFD700] text-xl font-bold mb-6 italic">₦{recommendation.product.price.toLocaleString()}</p>
                <div className="bg-zinc-900/50 p-4 rounded-xl border border-zinc-800 mb-8 italic text-zinc-300 text-sm">
                  "{recommendation.reason}"
                </div>
                <div className="flex flex-col gap-4">
                  <button
                    onClick={() => onAddToCart(recommendation.product)}
                    className="w-full bg-[#FFD700] text-black font-bold py-4 rounded-full flex items-center justify-center gap-2 hover:bg-white transition-all"
                  >
                    ADD TO CART <ShoppingCart size={18} />
                  </button>
                  <button
                    onClick={reset}
                    className="w-full border border-zinc-700 text-zinc-400 font-bold py-4 rounded-full flex items-center justify-center gap-2 hover:text-white transition-all"
                  >
                    RETAKE QUIZ <RefreshCw size={18} />
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ScentQuiz;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import Header from './components/Header';
import Footer from './components/Footer';
import CartDrawer from './components/CartDrawer';
import Home from './pages/Home';
import CategoryPage from './pages/CategoryPage';
import OrderPage from './pages/OrderPage';
import ScentQuiz from './pages/ScentQuiz';
import { CartItem, Product } from './types';

const App: React.FC = () => {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  // Load cart from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('cw_cart');
    if (saved) setCartItems(JSON.parse(saved));
  }, []);

  // Save cart to localStorage
  useEffect(() => {
    localStorage.setItem('cw_cart', JSON.stringify(cartItems));
  }, [cartItems]);

  const addToCart = (product: Product) => {
    setCartItems(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const updateQuantity = (id: string, delta: number) => {
    setCartItems(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  return (
    <Router>
      <div className="min-h-screen bg-black flex flex-col selection:bg-[#FFD700] selection:text-black">
        <Header cartCount={cartItems.reduce((a, b) => a + b.quantity, 0)} onCartClick={() => setIsCartOpen(true)} />

        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home onAddToCart={addToCart} />} />
            <Route path="/category/:categoryId" element={<CategoryPage onAddToCart={addToCart} />} />
            <Route path="/order" element={<OrderPage cartItems={cartItems} />} />
            <Route path="/quiz" element={<ScentQuiz onAddToCart={addToCart} />} />
          </Routes>
        </main>

        <Footer />

        <CartDrawer 
          isOpen={isCartOpen} 
          onClose={() => setIsCartOpen(false)} 
          items={cartItems} 
          onUpdateQuantity={updateQuantity}
          onRemove={removeFromCart}
        />
      </div>
    </Router>
  );
};

export default App;

