        return;
      }

      const nextText = isDeleting 
        ? currentPhrase.substring(0, displayText.length - 1)
        : currentPhrase.substring(0, displayText.length + 1);

      setDisplayText(nextText);
    };

    const typingTimer = setTimeout(handleTyping, typingSpeed);
