import { GoogleGenAI, Type } from "@google/genai";
import { PRODUCTS } from "./constants";

/**
 * World-class service for interacting with Google Gemini API.
 * Optimized for Vercel and Local environments.
 */

// Helper to safely access the API Key
const safeGetApiKey = () => {
  try {
    return process.env.API_KEY;
  } catch (e) {
    console.warn("process.env is not accessible in this context.");
    return undefined;
  }
};

// Helper to convert file to base64 for Gemini
const fileToBase64 = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      // Remove data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export async function getScentRecommendation(answers: { mood: string, occasion: string, preference: string }) {
  const apiKey = safeGetApiKey();
  if (!apiKey) throw new Error("API_KEY_MISSING");

  try {
    const ai = new GoogleGenAI({ apiKey });

    const prompt = `You are a world-class fragrance expert for Classic Wave Store at UNILAG.
    Based on these user preferences:
    - Mood: ${answers.mood}
    - Occasion: ${answers.occasion}
    - Scent Preference: ${answers.preference}

    Select the single most relevant product from this catalog: ${JSON.stringify(PRODUCTS.map(p => ({id: p.id, name: p.name, desc: p.description})))}.
    Return the choice in JSON format.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            productId: { type: Type.STRING, description: "The ID of the recommended product" },
            reason: { type: Type.STRING, description: "A one-sentence luxury explanation of why this matches" }
          },
          required: ["productId", "reason"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response");
    return JSON.parse(text);
  } catch (error: any) {
    console.error("Scent Quiz Error:", error);
    throw error;
  }
}

export async function generateProductImage(productName: string, aspectRatio: string = "1:1") {
  const apiKey = safeGetApiKey();
  if (!apiKey) throw new Error("API_KEY_MISSING");

  try {
    const ai = new GoogleGenAI({ apiKey });

    const prompt = `High-end commercial photography of a luxury fragrance bottle. 
    Product Name: "${productName}"
    Visual Elements: Premium glass bottle, exquisite cap design, soft dramatic studio lighting, 8k resolution, elegant atmosphere.
    Setting: Placed on a dark reflective marble surface with a soft mist in the background.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
          imageSize: "1K" // Defaulting to 1K for speed/stability
        }
      }
    });

    // Iterate through parts to find the image as per SDK guidelines
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data returned from Gemini");
  } catch (error: any) {
    console.error("Studio Generation Error:", error);
    throw error;
  }
}

export async function analyzeProductImage(imageFile: File) {
  const apiKey = safeGetApiKey();
  if (!apiKey) throw new Error("API_KEY_MISSING");

  try {
    const ai = new GoogleGenAI({ apiKey });
    const base64Data = await fileToBase64(imageFile);

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: imageFile.type,
              data: base64Data
            }
          },
          {
            text: "You are a luxury fragrance connoisseur. Analyze this image. If it shows a perfume or beauty product, identify it (or describe its style), guess its likely scent notes, suggest who would wear it (persona), and describe the 'vibe' of the packaging. If it's not a perfume, politely explain what you see in a sophisticated tone."
          }
        ]
      }
    });

    return response.text;
  } catch (error: any) {
    console.error("Image Analysis Error:", error);
    throw error;
  }
}

